local __PrefabPath = "QiMenDunJia/sceneObject/"

-- 奇门遁甲 格子管理类
---@class QiMenDunJiaGridMgr @
local M = class("QiMenDunJiaGridMgr")

function M:init(parentModel)
    self:initAllObjInfo()       
    self.parentModel = parentModel
    -- 走过的地块
    self:refreshWalkGrids(parentModel.serverMapData.passed)
    -- prefabPath
    -- 地图id
    self.map_id = self.parentModel.map_id
    -- 当前玩家格子id
    local curPlayerGridId = self.parentModel.playerGridId
    -- 查看时的格子id
    self.lookGridId = curPlayerGridId
    -- 超过x范围刷新脚下格子
    self.refreshRadius = 3
    -- 上一次刷新格子记录的格子id
    --self.lastRefreshGridId = curPlayerGridId
    -- 显示格子的范围
    self.showGridRadius = self.refreshRadius * 2
    -- 格子预制体
    self.viewGridObjCount = self.showGridRadius * self.showGridRadius
    -- 记录显示的格子对象集合
    self.showGridObjInfoList = {}
    
    -- [index]:gridId
    self.viewGridObjIdList = {}
    self.viewGridObjPool = nil
    self:initGridObjPool()      -- self.viewGridObjPool
    
    self:initGridsData()        -- self.gridUnitList
    self:refreshGridInfo(false, curPlayerGridId, true)
end

-- 刷新走过的格子数据
function M:refreshWalkGrids(passed)
    if not self.walkGridIds then
        self.walkGridIds = {}
    end
    for _, gridId in pairs(passed) do
        self.walkGridIds[gridId] = gridId
    end
    self.parentModel:refreshServerMapData({passed = self.walkGridIds})
end

-- 刷新单个走过的格子数据
function M:setWalkGridIdsByGridId(gridId)
    self.walkGridIds[gridId] = gridId
    self.parentModel:refreshServerMapData({passed = self.walkGridIds})
end

function M:isGridWalk(gridId)
    return (self.walkGridIds[gridId] ~= nil)
end

