function M:createGridObjByGridModelType(gridModelName) 
    local obj = ResourceUtil:GetUIItem("QiMenDunJia/sceneObject/"..gridModelName, self.gridPoolTrans.gameObject, "ui_prefabs")
    local itemGridTrans = obj.transform
    itemGridTrans.localPosition = Vector3.zero
    obj:SetActive(false)
    return obj
end

function M:setGridObjPosByGridId(gridObj, gridId)
    if IsNull(gridObj) then
        return
    end
    local gridUnit = self.gridUnitList[gridId]
    if not gridUnit then
        gridObj:SetActive(false)
        return
    end
    gridObj.transform.localPosition = Vector3(gridUnit.m_posX, gridUnit.m_posY, gridUnit.m_posZ)
end

-- 初始化格子数据
function M:initGridsData()
    self.gridUnitList = {}
    self.serverGridsData = self.parentModel.serverMapData.cells
    local local_mapData = require("Battle.Data.QiMenDunJia."..tostring(self.map_id));       
    --宽度
    local max_w = #local_mapData[0];
    --高度
    local max_h = #local_mapData;
    local gridUnitCls = require("Battle.Sce.QiMenDunJia.QiMenDunJiaGridUnit")
    for curWidth = 0, max_w do
        for curHeight = 0, max_h do
            -- 地图编辑器生成的数据是高在前
            local placeGridData = local_mapData[curHeight][curWidth] 
            local gridId = self:getGridIDByWidthAndHeight(curWidth,curHeight)
            local girdUnit = gridUnitCls.new()
            girdUnit:init(gridId, placeGridData, curWidth, curHeight)
            local serverGridData = self.serverGridsData[tostring(gridId)] or nil
            girdUnit:refreshGridData(serverGridData, (self.walkGridIds[gridId] ~= nil))
            self:setGridRelation(placeGridData, girdUnit)
            self:setMonsterRefreshGridRelation(girdUnit)
            self.gridUnitList[girdUnit.m_gridId] = girdUnit
        end
    end
    
    local centerGridData = self.gridUnitList[self.parentModel.playerGridId]
    -- 初始化将所在范围6个格子属性全部修改掉
    local aroundGridUnits,_ = self.parentModel:getAroundGridUnit(centerGridData)
    for _, itemUnit in pairs(aroundGridUnits) do
        if self.gridUnitList[itemUnit.m_gridId] then
            local girdUnit = self.gridUnitList[itemUnit.m_gridId]
            self.walkGridIds[girdUnit.m_gridId] = girdUnit.m_gridId
            local serverGridData = self.serverGridsData[tostring(itemUnit.m_gridId)] or nil
            girdUnit:refreshGridData(serverGridData, true)
            self.parentModel:refreshAStarGridData(itemUnit.w_pos, itemUnit.h_pos, serverGridData, true)
        end
    end
end

-- 设置八卦阵--柱子类格子关联
function M:setMonsterRefreshGridRelation(girdUnit)
    local mapConfig = self.parentModel.config
    if (mapConfig == nil) or (table.nums(mapConfig) <= 0) then
        return
    end
    local curGridId = girdUnit.m_gridId
    if mapConfig[curGridId] == nil then
        return
    end
    local curGridConfig = mapConfig[curGridId]
    local monsterRelationList = curGridConfig.monsterRelationList
    if (not monsterRelationList) or (monsterRelationList == "") then
        return
    end
    local monsterRelationInfoList = string.split(monsterRelationList, "|")
    if not monsterRelationInfoList[1] then
        return
    end
    if table.nums(monsterRelationInfoList) > 1 then
        girdUnit:setWuzhuangSign(true)
    else
        local itemInfo = monsterRelationInfoList[1]
        local relationGridData = string.split(itemInfo, "_")
        local tempGridId = self:getGridIDByWidthAndHeight(tonumber(relationGridData[1]), tonumber(relationGridData[2]))
        girdUnit:setMonsterRefreshGridId(tempGridId)
    end 
end

-- 设置格子关联
function M:setGridRelation(placeGridData, girdUnit)
    if (not placeGridData) or (not girdUnit) then
        return
    end
    --if girdUnit.m_gridType ~= GlobalConfig.GridType.Dependency then
    --    return
    --end
    local relationInfo = placeGridData.relationList
    if not relationInfo or relationInfo == "" then
        return
    end
    local relationInfoList = string.split(relationInfo, "|")
    if not relationInfoList[1] then
        return
    end
    local listCount = table.nums(relationInfoList)
    if listCount > 1 then
        -- 母格子
        local childList = {}
        for index = 1, listCount do
            local itemInfo = relationInfoList[index]
            local relationGridId = self:getGridIdByOneGridStrInfo(itemInfo)
            if relationGridId > 0 then
                childList[relationGridId] = relationGridId
            end
        end
        girdUnit:setRelationGridlist(childList)
        girdUnit:setRelationGridId(girdUnit.m_gridId)
    else
        -- 子格子
        local relationGridId = self:getGridIdByOneGridStrInfo(relationInfoList[1])
        if relationGridId > 0 then
            girdUnit:setRelationGridId(relationGridId)
        end
    end
end

-- 获取格子，通过格子string信息("2_2")
function M:getGridIdByOneGridStrInfo(gridStrInfo)
    local relationGridData = string.split(gridStrInfo, "_")
    if (not relationGridData) or (table.nums(relationGridData) < 2) then
        return -1
    end
    return self:getGridIDByWidthAndHeight(tonumber(relationGridData[1]), tonumber(relationGridData[2]))
end

