--销毁
function M:destroy()
    local gve_massifData = ConfigManager:getCfgByName("gve_massif")
    if self.viewGridObjPool then
        for gridModelType, itemGridPool in pairs(self.viewGridObjPool) do
            local gridXlsxData = gve_massifData[gridModelType] or {}
            local gridModelName = gridXlsxData.building_model
            if gridModelName then
                for _, gridObj in pairs(itemGridPool) do
                    if not IsNull(gridObj) then
                        self:setGridObjClickEvent(gridObj, false)
                        U3DUtil:DestroyAndBundle(gridObj,__PrefabPath..gridModelName,nil,0)
                    end
                end
            end
        end 
    end
    self.viewGridObjPool = nil

    if self.showGridObjInfoList then
        for _, itemData in pairs(self.showGridObjInfoList) do
            local gridModelType = itemData.gridModelType
            local gridXlsxData = gve_massifData[gridModelType] or {}
            local gridModelName = gridXlsxData.building_model
            if (not IsNull(itemData.gridObj)) and gridModelName then
                self:setGridObjClickEvent(itemData.gridObj, false)
                U3DUtil:DestroyAndBundle(itemData.gridObj,__PrefabPath..gridModelName,nil,0)
            end
        end
    end
    self.showGridObjInfoList = nil
    self.walkGridIds = nil
    for _, itemData in pairs(self.gridUnitList) do
        itemData:destroy()
    end
    self.gridUnitList = nil
end

-- 获得id     -- infoToID
function M:getGridIDByWidthAndHeight( w, h )
    --  110001 0001 0001
    return tonumber(self.map_id) * 100000000 + w * 10000 + h
end

--获取格子数据        -- getCellData
function M:getGridUnitById( cell_id )
    return self.gridUnitList[cell_id] or nil
end

return M